:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #253b3a;
  background: #f4efe5;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --coral: #e87962;
  --teal: #43a89b;
  --gold: #efc45f;
}

* { box-sizing: border-box; }
body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  padding: 28px 16px;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at top, #fffaf0 0, #f4efe5 68%);
}
.card {
  width: min(100%, 500px);
  padding: clamp(24px, 6vw, 40px);
  border: 1px solid #e7dece;
  border-radius: 28px;
  background: #fffdf8;
  box-shadow: 0 18px 55px #354b3d17;
  text-align: center;
}
.eyebrow {
  margin: 0 0 8px;
  color: #66817a;
  font-size: .82rem;
  font-weight: 750;
  letter-spacing: .12em;
  text-transform: uppercase;
}
h1 { margin: 0; font-size: clamp(1.8rem, 7vw, 2.4rem); line-height: 1.12; }
.intro { max-width: 340px; margin: 14px auto 26px; color: #60716d; line-height: 1.55; }
.game { max-width: 380px; margin: 0 auto; }
.status-row { min-height: 42px; display: flex; align-items: center; justify-content: space-between; gap: 12px; text-align: left; }
.moves { margin: 0; color: #60716d; font-weight: 650; }
.moves span { display: inline-grid; min-width: 30px; height: 30px; margin-left: 5px; place-items: center; border-radius: 10px; background: #edf3ed; color: #253b3a; }
.message { margin: 0; color: #51776f; font-weight: 700; text-align: right; }
.grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 7px;
  width: 100%;
  margin: 12px auto 24px;
  padding: 10px;
  border-radius: 18px;
  background: #eff1e8;
}
.tile {
  aspect-ratio: 1;
  min-width: 0;
  padding: 0;
  border: 0;
  border-radius: 8px;
  cursor: pointer;
  transition: transform 120ms ease, filter 120ms ease, box-shadow 120ms ease;
}
.tile.coral, .swatch.coral { background: var(--coral); }
.tile.teal, .swatch.teal { background: var(--teal); }
.tile.gold, .swatch.gold { background: var(--gold); }
.tile:hover { transform: scale(1.07); filter: brightness(1.06); }
.tile:active { transform: scale(.94); }
.tile:focus-visible { outline: 3px solid #253b3a; outline-offset: 2px; z-index: 1; }
.palette { margin: 0; padding: 0; border: 0; }
.palette legend { width: 100%; margin-bottom: 12px; color: #60716d; font-weight: 650; }
.color-options { display: flex; justify-content: center; gap: 10px; }
.color-button, .reset-button {
  min-height: 48px;
  border: 1px solid #d9e0d7;
  border-radius: 14px;
  background: #fffdf8;
  color: #253b3a;
  font: inherit;
  font-weight: 650;
  cursor: pointer;
  transition: background 120ms ease, transform 120ms ease, border-color 120ms ease;
}
.color-button { display: inline-flex; align-items: center; gap: 8px; padding: 0 13px; }
.swatch { width: 18px; height: 18px; border-radius: 6px; }
.color-button:hover, .reset-button:hover { background: #f1f5ee; border-color: #a9bdb0; }
.color-button:active, .reset-button:active { transform: translateY(1px) scale(.98); }
.color-button[aria-pressed="true"] { border: 2px solid #42645c; background: #edf4ed; }
.color-button:focus-visible, .reset-button:focus-visible { outline: 3px solid #42645c; outline-offset: 3px; }
.reset-button { width: 100%; margin-top: 16px; }
.hint { margin: 22px 0 0; color: #77847a; font-size: .92rem; }
[hidden] { display: none !important; }
@media (max-width: 390px) {
  body { padding: 18px 12px; }
  .grid { gap: 5px; padding: 8px; }
  .color-options { gap: 7px; }
  .color-button { gap: 6px; padding: 0 9px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; }
}

const initialBoard = [
  ['coral', 'coral', 'teal', 'teal', 'gold', 'gold'],
  ['coral', 'teal', 'teal', 'gold', 'gold', 'coral'],
  ['coral', 'coral', 'gold', 'gold', 'teal', 'coral'],
  ['teal', 'coral', 'gold', 'teal', 'teal', 'coral'],
  ['teal', 'teal', 'gold', 'gold', 'coral', 'coral'],
  ['gold', 'teal', 'teal', 'coral', 'coral', 'gold']
];
const grid = document.querySelector('#grid');
const moveCount = document.querySelector('#move-count');
const message = document.querySelector('#message');
const colorButtons = [...document.querySelectorAll('.color-button')];
let board;
let moves;
let selectedColor = 'coral';

function isUniform() {
  return board.every(row => row.every(color => color === board[0][0]));
}

function render() {
  grid.replaceChildren();
  board.forEach((row, r) => row.forEach((color, c) => {
    const tile = document.createElement('button');
    tile.type = 'button';
    tile.className = `tile ${color}`;
    tile.setAttribute('aria-label', `Row ${r + 1}, column ${c + 1}, ${color}`);
    tile.addEventListener('click', () => play(r, c));
    grid.append(tile);
  }));
  moveCount.textContent = String(moves);
  message.textContent = isUniform() ? 'One color!' : 'Pick a color to begin.';
}

function play(row, col) {
  if (isUniform()) return;
  const target = board[row][col];
  if (target === selectedColor && board[0][0] === selectedColor) {
    message.textContent = 'Choose a different color.';
    return;
  }

  const connected = new Set();
  const queue = [];
  for (let r = 0; r < 6; r++) {
    for (let c = 0; c < 6; c++) {
      if (board[r][c] === board[0][0]) {
        const index = r * 6 + c;
        connected.add(index);
        queue.push([r, c]);
      }
    }
  }
  for (let i = 0; i < queue.length; i++) {
    const [r, c] = queue[i];
    for (const [nr, nc] of [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]]) {
      const index = nr * 6 + nc;
      if (nr >= 0 && nr < 6 && nc >= 0 && nc < 6 && !connected.has(index) && board[nr][nc] === target) {
        connected.add(index);
        queue.push([nr, nc]);
      }
    }
  }
  for (const index of connected) board[Math.floor(index / 6)][index % 6] = selectedColor;
  moves++;
  render();
  if (!isUniform()) message.textContent = `Area filled with ${selectedColor}.`;
}

colorButtons.forEach(button => button.addEventListener('click', () => {
  selectedColor = button.dataset.color;
  colorButtons.forEach(option => option.setAttribute('aria-pressed', String(option === button)));
  if (!isUniform()) message.textContent = `Selected ${selectedColor}. Click a tile.`;
}));

document.querySelector('#reset').addEventListener('click', () => {
  board = initialBoard.map(row => [...row]);
  moves = 0;
  render();
});

board = initialBoard.map(row => [...row]);
moves = 0;
render();
